 [Parameter(Mandatory=$true)][string]$EntrypointPath,[Parameter(Mandatory=$true)][string]$EntrypointSha256,[Parameter(Mandatory=$true)][string]$ResponderCorePath,[Parameter(Mandatory=$true)][string]$ResponderCoreSha256,
